def catch_exception(f):
    @functools.wraps(f)
    def func(*args, **kwargs):
        retry_counter = 0
        try:
            return f(*args, **kwargs)
        except ConnectionException:
            for retry_counter in range(60):
                sleep(5)
                print("[{:%Y-%m-%d %H:%M:%S}] retry #{}".format(datetime.now(), retry_counter))
                logger.debug('BCF connected after {} retries in catch_exception'.format(retry_counter))
                try:
                    return f(*args, **kwargs)
                except:
                    continue
            else:
                raise ConnectionException("BCF not connected after {} retries!".format(retry_counter + 1))
        except Exception as e:
            if (str(e).find('exceptions.UnicodeEncodeError') != -1) or (str(e).find('function takes exactly 5 arguments') != -1):
                return ['Could not read log message from server']
            else:
                raise e

    return func


