    def setup_elementmanager(self, **kwargs):
        r"""
        Keyword used to setup both Element Manager and Pyro server.

        |:author: RFS TSR TA Team
        |:contact: I_BTSAUTO_DEV_TSR@internal.nsn.com
        |:maintainer: RFS TSR TA Team
        |:contact: I_BTSAUTO_DEV_TSR@internal.nsn.com

        **Input Parameters:**

        +---------------------------------+------+------------------------------------------+
        | Parameter name                  | Man. | Description                              |
        +=================================+======+==========================================+
        | element_manager_pc_ip           | Yes  | Remote Element Manager PC(ElM PC) IP Addr|
        +---------------------------------+------+------------------------------------------+
        | ssh_user                        | No   | SSH username to Element Manager PC       |
        +---------------------------------+------+------------------------------------------+
        | ssh_password                    | No   | SSH password to Element Manager PC       |
        +---------------------------------+------+------------------------------------------+
        | remotelibpath                   | No   | Destination Path for files (on ElM PC)   |
        +---------------------------------+------+------------------------------------------+
        | pyro_port                       | No   | Port on ElM PC where Pyro Server listens |
        +---------------------------------+------+------------------------------------------+
        | pyro_server_name                | No   | Name of the pyro server to register URI  |
        +---------------------------------+------+------------------------------------------+
        | bts_host                        | No   | 2GBTS IP address for ElM 2G to connect to|
        +---------------------------------+------+------------------------------------------+
        | bts_port                        | No   | 2GBTS Port for ElM 2G to connect to      |
        +---------------------------------+------+------------------------------------------+
        |  bts_password                   | No   |  2G BTS Element Manager Password         |
        +---------------------------------+------+------------------------------------------+
        |  bcf_number                     | No   |  2G BTS BCF number                       |
        +---------------------------------+------+------------------------------------------+

        | **Return value**
        | True if successful, False otherwise

        **Example**:
        
        .. code-block::  robotframework

          ${result}  Setup Pyro  element_manager_pc_ip=10.5.22.77  ssh_user=rfsharing  ssh_password=xxxx  bcfnumber=1032

        """

        self.defaults.update(kwargs)
        kwargs = self.defaults.copy()
        self.pyro_client = ElementManagerClient(**kwargs)
        self.pyro_client.connect()
        self._pyro_instance = self.pyro_client.pyro_client_object
        if self._pyro_instance:
            sys.excepthook = Pyro4.util.excepthook
            return True
        else:
            return False

    def _setup_pyro_for_traces(self, **kwargs):
        self.pyro_client = ElementManagerClient(**kwargs)
        self.pyro_client_traces = ElementManagerClient(**kwargs)
        self.pyro_client_traces.connect()
        self._pyro_instance_traces = self.pyro_client_traces.pyro_client_object
        if self._pyro_instance_traces:
            return True
        else:
            return False

    def connect_to_bcf(self, timeout=45):
        r"""
        Keyword used to connect to BCF. Connection attempt is handled internally for 6 times until successful.
        Upon successful connection BCF State will be printed (ex. "BCF state is: Supervisory').

        Connection to BCF is maintained until disconnect KW is called explicitly. If BCF drops the connection
        for whatever reason, reconnection will be handled internally, transparent to the user (similar to the
        BTS Site Manager Windows application).
        In case of an unhandled/unexpected script failure, BCF will automatically close any unresponsive connection
        after 15 seconds.

        |:author: RFS TSR TA Team
        |:contact: I_BTSAUTO_DEV_TSR@internal.nsn.com
        |:maintainer: RFS TSR TA Team
        |:contact: I_BTSAUTO_DEV_TSR@internal.nsn.com

        **Input Parameters:**
        
        +---------------------------------+------+------------------------------------------+
        | Parameter name                  | Man. | Description                              |
        +=================================+======+==========================================+
        | timeout                         | No   | Timeout in seconds for connection to BCF |
        +---------------------------------+------+------------------------------------------+

        | **Return value**
        | Tuple with execution result (True/False) if connection successful and list with output messages from
        | execution. If retries are unsuccessful(or timed out), KW will fail.

        **Example**:

        .. code-block::  robotframework

          ${success}  ${logs}  Connect To BCF  timeout=45

        Output example (${success},  ${logs})
        (True, [u'element_manager_pyro_server_running', u'\n', u'Trying to connect to BCF 1024...', u'\n',
        u'Event: Alarm = AlarmDetail: 302 Local MMI connected', u'\n', u'Event: BCF ', u' ', u'1024', u' ',
        u' connected', u'\n', u'Successfully connected to 2G BTS, BCF id: 1024', u'\n', u'BCF state is: Supervisory',
        u'\n', u"['element_manager_pyro_server_running', '\\n', 'Trying to connect to BCF 1024...', '\\n',
        'Event: Alarm = AlarmDetail: 302 Local MMI connected', '\\n', 'Event: BCF ', ' ', '1024', ' ',
        ' connected', '\\n', 'Successfully connected to 2G BTS, BCF id: 1024', '\\n',
        'BCF state is: Supervisory', '\\n']", u'\n'])
        """

        try:
            return run_kw_with_timeout(runnable=self._pyro_instance.connect_to_bcf,
                                       timeout=timeout, timeout_msg='Timeout at connect'), self.get_logs()
        except Exception as e:
            logger.exception('Exception at connect to bcf: {}'.format(e))
            raise ConnectionException

    @catch_exception
    def bts_commissioning(self, scf_file, state_check_timeout=600):
        r"""
        Keyword used to load commissioning (.xml) file to BCF.
        Will fail if no connection to BTS is available or if BCF has improper state after commissioning
        (ie. 'Supervisory') or if BCF file is incorrect (not accepted by BCF).
        SCF file has to have some XML nodes renamed from default values when loaded with this interface and therefore
        it needs to be processed by XMLParser prior to loading to BCF. This is done automatically and transparent
        to the user.

        |:author: RFS TSR TA Team
        |:contact: I_BTSAUTO_DEV_TSR@internal.nsn.com
        |:maintainer: RFS TSR TA Team
        |:contact: I_BTSAUTO_DEV_TSR@internal.nsn.com

        **Input Parameters:**
        
        +---------------------------------+------+-------------------------------------------------+
        | Parameter name                  | Man. | Description                                     |
        +=================================+======+=================================================+
        | scf_file                        | Yes  | string, full path to .xml file (i.e.)           |
        |                                 |      | (/home/ute/btsauto/TARGET_SW_SLAVE/scf_file.xml)|
        +---------------------------------+------+-------------------------------------------------+
        | retry                           | No   | Number of attempts to load commissioning file   |
        +---------------------------------+------+-------------------------------------------------+
        | state_check_timeout             | No   | int, maximum wait time for BCF Commissioning    |
        |                                 |      |  or Supervisory state before loading SCF        |
        +---------------------------------+------+-------------------------------------------------+

        | **Return value**
        | Tuple with execution result (True/False) if successful and if BCF state changed properly,
        | Fail with 'ConnectionException' if no connection to BTS is available or if BCF has improper state after commissioning
        | (ie. 'Supervisory') or if BCF file is incorrect (not accepted by BCF) with 'CommissioningException'
        | and list with output messages from execution.

        **Example**:

        .. code-block::  robotframework

          ${success}  {logs}  BTS Commissioning

        """
        filename = scf_file[(scf_file.rfind('/') + 1):]  # should return only xml filename
        remote_folder = 'TARGET_SW_SLAVE'
        self._transfer_file_to_remote_ssh_host(remote_folder + '\\', scf_file, filename)
        userpath = self._get_current_user_homepath() + '\\' + remote_folder + '\\'
        return self._pyro_instance.bts_commissioning(scf_file=(userpath + filename), state_check_timeout=state_check_timeout), self.get_logs()

