    @catch_exception
    def request_sw_update(self, sw_path, load_all_files=True):
        r"""
        Keyword to perform SWDL/SW update to 2G BTS. It expects a BTS masterfile (ie. BTSR1653.F7X) as input
        and optionally a True/False flag to trigger download of all files to BTS or just new ones.
        Will return True if SWDL succeeds and False otherwise. Will fail if no connection to BTS is available.

        | :author: RFS TSR TA Team
        | :contact: I_BTSAUTO_DEV_TSR@internal.nsn.com
        | :maintainer: RFS TSR TA Team
        | :contact: I_BTSAUTO_DEV_TSR@internal.nsn.com

        **Input Parameters:**
        
        +---------------------------------+------+-------------------------------------------------+
        | Parameter name                  | Man. | Description                                     |
        +=================================+======+=================================================+
        |  sw_path                        | yes  | string, full path to BTS masterfile (i.e.       |
        |                                 |      | /home/ute/btsauto/TARGET_SW_SLAVE/BTSR1653.F7X) |
        +---------------------------------+------+-------------------------------------------------+
        |  load_all_files                 | no   | boolean, True or False                          |
        +---------------------------------+------+-------------------------------------------------+

        | **Return value**
        | True or False
        | Result:
        | Starting SW download. Please wait patiently ..
        | SwUpdate success
        | ${success} = 'True'


        **Example**:

        .. code-block::  robotframework

          ${success}  Request SW Update  ${path_to_masterfile}  ${load_all_files}

        """
        masterfile = sw_path[(sw_path.rfind('/') + 1):]  # should be something like BTSR1653.F7X
        path_to_masterfile = sw_path[:-12]
        remote_folder = 'TARGET_SW_SLAVE'
        self._transfer_folder_to_remote_host(remote_folder, path_to_masterfile)
        remote_path_to_sw = '{}'.format(self._get_current_user_homepath() + '\\' + remote_folder + '\\' + masterfile)
        logger.info('Triggering SWDL with {}'.format(sw_path))
        logger.debug('Remote path to masterfile {}'.format(remote_path_to_sw))
        return self._pyro_instance.request_sw_update(remote_path_to_sw, load_all_files), self.get_logs()

    @staticmethod
    def validate_sw_path(sw_path):
        r"""
        Keyword will get as argument a path to a folder where SW for SWDL resides. Will return latest written SW to
        disk in format PATH, MASTERFILE.

        | :author: RFS TSR TA Team
        | :contact: I_BTSAUTO_DEV_TSR@internal.nsn.com
        | :maintainer: RFS TSR TA Team
        | :contact: I_BTSAUTO_DEV_TSR@internal.nsn.com

        **Input Parameters:**
        
        +---------------------------------+------+-------------------------------------------------+
        | Parameter name                  | Man. | Description                                     |
        +=================================+======+=================================================+
        |  sw_path                        | yes  | string, path to software with no masterfile.    |
        |                                 |      | Will search for latest sw written to disk.      |
        +---------------------------------+------+-------------------------------------------------+

        | **Return value**
        | python tuple with 1st element PATH to SW and 2nd element MASTERFILE.


        **Example**:

        .. code-block::  robotframework

          ${Target SW dir val}  ${Target SW name val}  Validate SW Path  ${Target SW dir}

        """
        file_folder_dict = {}
        for root, subdir, files in walk(sw_path):
            files = [m.group(1) for m in [search(r'(BTS\w{5}\.\w{3})', str(files))] if m]
            # generates with list comprehension a list whose element is the match for a regex of a bts
            # masterfile (ie. BTSR1653.F7X) regexp'd from 'files' (which, in turn, contains a list of all filenames
            # in 'subdir'). if re.search returns no match, an empty list is generated.
            if len(files) > 0:
                files = files[0]
                try:
                    file_folder_dict[stat(root)[ST_MTIME]] = '{},{}'.format(root, files)
                    # will return a dictionary with key: modified time of file and value: full path to file, ie:
                    # {1500450233L: 'C:\\TEMP\\tmp\\GF16.5 2.3\\Flexi_Multiradio10_BTS_GF16.5_2.3_BL127_A51_A53-BTSR1653.7FX\\btspack_10.52-33\\A53\\BTSR1653.7FX',
                    # 1500463532L: 'C:\\TEMP\\tmp\\Flexi_Multiradio10_BTS_GF17_2.0_BL017_A51_A53-BTSR1703.11X\\btspack_11.02-03\\A53\\BTSR1703.11X'}
                except:
                    continue  # yes, we need this dictionary that badly!
                    # sort dictionary by key (which here represents the modified time of the file contained in 'value')
        file_folder_dict_sorted = sorted(file_folder_dict, reverse=True)
        # get first key from file_folder_dict, split it by ',' pack it into a tuple and return it
        # first element of tuple will contain smth like C:\TEMP\tmp\Flexi_Multiradio10_BTS_GF17_2.0_BL017_A51_A53-BTSR1703.11X\btspack_11.02-03\A53
        # second will contain bts masterfilename BTSR1703.11X
        try:
            return tuple(file_folder_dict[file_folder_dict_sorted[0]].split(','))
        except IndexError:
            logger.error("Error in parsing given SW path {}. Please check the folder's existence!".format(sw_path))
            raise

