    def stop_server(self, retun_cygwin_style_path=True, timeout=45):
        r"""
        Keyword used to stop pyro server daemon. Returns True if successful.
        Will also return path (cygwin style or optional windows style) to remote PC logs if pyro server shutdown was successful.
        If traces are activated, will also return logfile path for traces, if not, last tuple element will be the same
        as previous element.

        | :author: RFS TSR TA Team
        | :contact: I_BTSAUTO_DEV_TSR@internal.nsn.com
        | :maintainer: RFS TSR TA Team
        | :contact: I_BTSAUTO_DEV_TSR@internal.nsn.com

        **Input Parameters:**

        +---------------------------------+------+-------------------------------------------------+
        | Parameter name                  | Man. | Description                                     |
        +=================================+======+=================================================+
        | retun_cygwin_style_path         | No   |  True or False                                  |
        +---------------------------------+------+-------------------------------------------------+
        | timeout                         | No   |  Keyword execution timeout in seconds           |
        +---------------------------------+------+-------------------------------------------------+

        | **Return value**
        | Tuple with first element True and second and third element location to remote PC logs if successful,
        | tuple of True, True, True if pyro server shutdown was not successful.
        |        Result:
        | ${is_daemon_stopped} = (True,
        | u'/cygdrive/c/Program Files (x86)/IronPython 2.7/Lib/site-packages/hran_elementmanager2g/logs/elementmanager2g_Nov 14, 2017, 17 27 37.log',
        | u'/cygdrive/c/Program Files (x86)/IronPython 2.7/Lib/site-packages/hran_elementmanager2g/logs/elementmanager2g_Nov 14, 2017, 17 27 37.log')


        **Example**:

        .. code-block::  robotframework

          ${is_daemon_stopped}  ${logfile_location}  ${traces_logfile_location}  Stop Server

        """
        logger.debug("+++ Stop Server - START!")
        status, log1, log2 = run_kw_with_timeout(runnable=self._stop_pyro_server, timeout=timeout,
                                                 timeout_msg='stop pyro server timeout',
                                                 args=(retun_cygwin_style_path,))
        logger.debug("+++ Stop Server - STOP SUCCESSFULLY!")
        return status, log1, log2

    def _stop_pyro_server(self, retun_cygwin_style_path=True):
        r"""
        Keyword used to stop pyro server daemon. Returns True if successful.
        Will also return path (cygwin style or optional windows style) to remote PC logs if pyro server shutdown was successful.
        If traces are activated, will also return logfile path for traces, if not, last tuple element will be the same
        as previous element.

        | :author: RFS TSR TA Team
        | :contact: I_BTSAUTO_DEV_TSR@internal.nsn.com
        | :maintainer: RFS TSR TA Team
        | :contact: I_BTSAUTO_DEV_TSR@internal.nsn.com

        **Input Parameters:**
        
        +---------------------------------+------+-------------------------------------------------+
        | Parameter name                  | Man. | Description                                     |
        +=================================+======+=================================================+
        | retun_cygwin_style_path         | No   |  True or False                                  |
        +---------------------------------+------+-------------------------------------------------+

        | **Return value**
        | Tuple with first element True and second and third element location to remote PC logs if successful,
        | tuple of True, True, True if pyro server shutdown was not successful.
        |        Result:
        | ${is_daemon_stopped} = (True,
        | u'/cygdrive/c/Program Files (x86)/IronPython 2.7/Lib/site-packages/hran_elementmanager2g/logs/elementmanager2g_Nov 14, 2017, 17 27 37.log',
        | u'/cygdrive/c/Program Files (x86)/IronPython 2.7/Lib/site-packages/hran_elementmanager2g/logs/elementmanager2g_Nov 14, 2017, 17 27 37.log')


        **Example**:

        .. code-block::  robotframework

           ${is_daemon_stopped}  ${logfile_location}  ${traces_logfile_location} | Stop Server

        """
        if self._pyro_instance is not None:
            logger.info("safely stopping pyro daemon...")
            try:
                logger.debug("start - return logfile path")
                logfile = self._pyro_instance.logfile_path()
                if retun_cygwin_style_path:
                    logger.debug("start - convert windows to cygwin path")
                    logfile = self._pyro_instance.convert_windows_to_cygwin_path(logfile)
                logger.debug("start - send stop server to pyro server")
                self._pyro_instance.stop_server()
                logfile_traces = logfile
                if self._pyro_instance_traces:
                    logger.debug("start - return logfile path for pyro traces")
                    logfile_traces = self._pyro_instance_traces.logfile_path()
                    if retun_cygwin_style_path:
                        logger.debug("start - convert windows to cygwin path, pyro traces")
                        logfile_traces = self._pyro_instance_traces.convert_windows_to_cygwin_path(logfile_traces)
                        self._pyro_instance_traces.stop_server()
                logger.debug("start - cleanup pyro 1")
                self.__cleanup_pyro()
                return True, logfile, logfile_traces
            except Exception as e:
                logger.exception("stop pyro server exception: {}".format(e))
                logger.debug("start - cleanup pyro 2")
                self.__cleanup_pyro()
                return True, True, True
        return True, True, True

    def __cleanup_pyro(self):
        self._pyro_instance = None
        self._pyro_instance_traces = None
        self.pyro_client = None
        self.pyro_client_traces = None
        return True

