    def _unbzip(self, local_file, local_file_uncompressed):
        try:
            with open(local_file_uncompressed, 'w') as new_file, BZ2File(local_file) as bz2file:
                for data in iter(lambda: bz2file.read(100 * 1024), b''):
                    new_file.write(data)
        except EOFError:
            logger.error('Invalid SCF name provided. Please check filename extension (should be .bz2!)')
            raise
        except IOError:
            logger.debug('SCF file has already been received in XML format, nothing to unzip here.')
            rename(local_file, local_file_uncompressed)
            return local_file_uncompressed, self.get_logs()
        logger.info('SCF file saved to {}'.format(local_file_uncompressed))
        return local_file_uncompressed, self.get_logs()

    @catch_exception
    def save_scf_file(self, local_file=None, unzip=True):
        r"""
        Method used to get SCF file from BTS. (If this code runs in RFS on Master VM,
        it will put the SCF on that machine)

        | :author: RFS TSR TA Team
        | :contact: I_BTSAUTO_DEV_TSR@internal.nsn.com
        | :maintainer: RFS TSR TA Team
        | :contact: I_BTSAUTO_DEV_TSR@internal.nsn.com

        **Input Parameters:**
        
        +---------------------------------+------+--------------------------------------------------------------+
        | Parameter name                  | Man. | Description                                                  |
        +=================================+======+==============================================================+
        |       local_file                | No   | String, full path with filename.bz2 for local scf,           |
        |                                 |      | ie. /home/ute/btsauto/logs/scf.bz2                           |
        +---------------------------------+------+--------------------------------------------------------------+
        |       unzip                     | No   | Boolean; indicates if SCF should be a zip archive or unpacked|
        +---------------------------------+------+--------------------------------------------------------------+

        | **Return value**
        | Touple containing result of SCF file save (True/False),
        | and a list of logging messages

        **Example**:

        .. code-block::  robotframework

           ${result}  ${logs}  Save scf file  local_file=/tmp/file.xml

        """
        if not local_file:
            print('in save SCF file, not local_file, interface')
            local_file = path.expanduser('~') + sep + 'SCF_{:%b%d%Y_%H_%M_%S}'.format(datetime.now()) + '.bz2'
            local_file_uncompressed = path.expanduser('~') + sep + 'SCF_{:%b%d%Y_%H_%M_%S}'.format(datetime.now()) + '.xml'
        else:
            print('in save SCF file, local_file, interface')
            local_file_uncompressed = str(local_file).replace('.bz2', '.xml')
        remote_scf_file = self._pyro_instance.save_scf_file()
        print('after save SCF file, interface')
        print('after save SCF file, remote_scf_file={}, type {}'.format(remote_scf_file, type(remote_scf_file)))
        dir_only = remote_scf_file[:(remote_scf_file.rfind('\\') + 1)]
        print('after save SCF file, dir_only={}, type {}'.format(dir_only, type(dir_only)))
        filename_only = remote_scf_file[(remote_scf_file.rfind('\\') + 1):]
        print('after save SCF file, filename_only={}, type {}'.format(filename_only, type(filename_only)))
        if remote_scf_file:
            self._transfer_file_from_remote_ssh_host(dir_only, filename_only, local_file)
            if path.getsize(local_file) > 0:
                if unzip:
                    return self._unbzip(local_file, local_file_uncompressed)
                else:
                    logger.info('SCF file saved to {}'.format(local_file))
                    print('SCF file saved to {}'.format(local_file))
                    return local_file, self.get_logs()
            else:
                logger.error('Could not copy SCF file to local machine.')
                print('Could not copy SCF file to local machine.')
                return False, self.get_logs()
        else:
            logger.error('Could not create SCF file.')
            print('Could not create SCF file.')
            return False, self.get_logs()

    @catch_exception
    def get_scf_parameter(self, searchitem, itemtype, destination_path='/tmp'):
        r"""
        Keyword used to get a value from xml file using the (xpath, string, regex) expression in argument.
        - SCF will be downloaded
        - a search will be performed on the downloaded SCF

        | :author: RFS TSR TA Team
        | :contact: I_BTSAUTO_DEV_TSR@internal.nsn.com
        | :maintainer: RFS TSR TA Team
        | :contact: I_BTSAUTO_DEV_TSR@internal.nsn.com

        **Input Parameters:**
        
        +---------------------------------+------+--------------------------------------------------------------+
        | Parameter name                  | Man. | Description                                                  |
        +=================================+======+==============================================================+
        |       searchitem                | No   | parameter or expression containing parameter read from scf   |
        +---------------------------------+------+--------------------------------------------------------------+
        |       itemtype                  | No   | type of the above parameter (string, xpath , regex)          |
        +---------------------------------+------+--------------------------------------------------------------+
        |     destination_path            | No   | path (on VM) where to find scf xml file                      |
        +---------------------------------+------+--------------------------------------------------------------+

        | **Return value**
        | list containing read value(s)

        **Example**:

        .. code-block::  robotframework

           ${result}  ${logs}  Get SCF parameter  searchitem=.//*[local-name()=\'p\'][(@name=\'tempSyncMasterRecovTime\')
                      or (@name=\'tempSyncMasterTriggerTime\')][text()=255]
           xpath  ${BTSFiles}/Slave

        """
        from lxml import etree as ET
        max_retry = 3
        response = []
        logs = ""
        if searchitem == "":
            logs = "Empty searchitem argument"
            return response, logs
        if itemtype not in {'string', 'regex', 'xpath'}:
            logs = "Wrong itemtype argument: must be one of   string, regex, xpath"
            return response, logs
        local_file = False
        while not (local_file) and max_retry > 0:
            local_file, logs = self.save_scf_file(local_file=r'{}/SCF_{:%b%d%Y_%H_%M_%S}.bz2'.format(destination_path,
                                                                                                    datetime.now()))
            max_retry -= 1
        if local_file:
            #  decide what kind of input we have
            with open(local_file) as f:
                data = ET.parse(f)
            if itemtype == 'string' or itemtype == 'xpath':
                response = data.xpath(searchitem)
                return response, logs
            else:
                with open(local_file) as f:
                    for line in f:
                        m = findall(searchitem, line)
                        if m != []:
                            response = response + list(m)
                return response, logs
        else:
            raise ElementManager2GError('Could not create SCF file.')

