    @catch_exception
    def get_RSSI_difference_list_GSM(self):
        r"""
        Keyword used to get differences between raw RSSI main values and (div1,2,3,
        whichever is different from 255) from BTS, for all TRX.

        | :author: RFS TSR TA Team
        | :contact: I_BTSAUTO_DEV_TSR@internal.nsn.com
        | :maintainer: RFS TSR TA Team
        | :contact: I_BTSAUTO_DEV_TSR@internal.nsn.com

        **Input Parameters:**

        +---------------------------------+------+-------------------------------------------------+
        | Parameter name                  | Man. | Description                                     |
        +=================================+======+=================================================+
        | None                            |      |                                                 |
        +---------------------------------+------+-------------------------------------------------+

        | **Return value**
        | A list of integers containing differences between RSSI
        | for all TRX where we have a call going on (list_samples != 0)

        **Example**:

        .. code-block::  robotframework

          ${log_list}  Get Logs Traces

        """
        list_rssi_main, list_rssi_div1, list_rssi_div2, list_rssi_div3, list_samples = \
            self._pyro_instance.get_raw_RSSI_values()
        list_differences = [abs(
            list_rssi_main[index] - self._get_div(list_rssi_div1[index], list_rssi_div2[index], list_rssi_div3[index]))
                            for index in range(len(list_samples)) if list_samples[index] > 0]
        return list_differences, self.get_logs()

    def _get_div(self, value1, value2, value3):
        if value1 != 1:
            return value1
        if value2 != 1:
            return value2
        if value3 != 1:
            return value3

