    def bts_mng_cli_fetch_snapshot(self, timeout=1800):
        r"""
        Keyword launches the FETCH SNAPSHOT command on Bts Manager cli, waits for snapshot collection and in the end,
        transfers it on the local machine.

        | :author: RFS TSR TA Team
        | :contact: I_BTSAUTO_DEV_TSR@internal.nsn.com
        | :maintainer: RFS TSR TA Team
        | :contact: I_BTSAUTO_DEV_TSR@internal.nsn.com

        **Input Parameters:**
        +---------------------------------+------+-----------------------------------------------------------+
        | Parameter name                  | Man. | Description                                               |
        +=================================+======+===========================================================+
        |       timeout                   | No   | Max time to wait for the snapshot completion              |
        +=================================+======+===========================================================+

        **Example**:
        ..code-block::  robotframework

          ${result}  Bts Mng Cli Fetch Snapshot  timeout=1500

        """
        if not self.bts_mng_cli.open_BTS_Mng_cli_and_prepare_action_on_cli():
            self.bts_mng_cli.close_BTS_Mng_cli()
            return False
        return self.bts_mng_cli.fetch_snapshot(timeout) and self.bts_mng_cli.close_BTS_Mng_cli()
